+#include <cstdio.h>
+#include <cstdlib.h>
+#include <cstring.h>
+#include <unistd.h>
+#include <termios.h>
+#include <sys/select.h>
+#include <sys/time.h>
+#include <time.h>
+#include <signal.h>
+#include <ctype.h>
+#include <sys/ioctl.h>
+#include <sys/types.h>
+#include "options.h"
+
+// Global options
+static Options g_opts;
+
+// Matrix characters
+static const char *katakana_chars = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン";
+static const char *latin_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
+
+// Terminal state
+static struct termios orig_termios;
+static int raw_mode = 0;
+
+// Signal handler
+static void sigint_handler(int sig) {
+    (void)sig;
+    if (g_opts.screensaver) {
+        exit(0);
    }
}
+
+// Initialize terminal to raw mode
+static void init_terminal(void) {
+    if (tcgetattr(STDIN_FILENO, &orig_termios) == -1) {
+        perror("tcgetattr");
+        exit(1);
+    }
+    
+    struct termios raw = orig_termios;
+    raw.c_lflag &= ~(ECHO | ICANON);
+    raw.c_cc[VMIN] = 0;
+    raw.c_cc[VTIME] = 0;
+    
+    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) == -1) {
+        perror("tcsetattr");
+        exit(1);
+    }
+    raw_mode = 1;
+}
+
+// Restore terminal settings
+static void restore_terminal(void) {
+    if (raw_mode) {
+        if (tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios) == -1) {
+            perror("tcsetattr");
+            exit(1);
+        }
+        raw_mode = 0;
+    }
+}
+
+// Print a single line of matrix
+static void print_line(const char *line, int color) {
+    static const char *colors[] = {
+        "\033[32m",  // green (default)
+        "\033[31m",  // red
+        "\033[34m",  // blue
+        "\033[37m",  // white
+        "\033[33m",  // yellow
+        "\033[36m",  // cyan
+        "\033[35m",  // magenta
+        "\033[0m"    // reset
+    };
+    
+    if (color >= 0 && color < 8) {
+        printf("%s", colors[color]);
+    }
+    
+    if (g_opts.bold_chars || g_opts.all_bold) {
+        printf("\033[1m");
+    }
+    
+    printf("%s", line);
+    
+    if (g_opts.bold_chars || g_opts.all_bold) {
+        printf("\033[0m");
+    }
+    
+    printf("\033[0m");
+}
+
+// Generate a random line
+static void generate_line(char *line, int width) {
+    int i;
+    for (i = 0; i < width; i++) {
+        int char_idx = rand() % (strlen(katakana_chars) + strlen(latin_chars));
+        if (char_idx < (int)strlen(katakana_chars)) {
+            line[i] = katakana_chars[char_idx];
+        } else {
+            line[i] = latin_chars[char_idx - strlen(katakana_chars)];
+        }
+    }
+    line[width] = '\0';
+}
+
+// Main function
+int main(int argc, char *argv[]) {
+    int width, height;
+    char *line_buffer;
+    int i;
+    struct timeval tv;
+    fd_set readfds;
+    int ret;
+    
+    // Initialize options
+    options_init(&g_opts);
+    
+    // Parse command line
+    options_parse(argc, argv, &g_opts);
+    
+    // Handle help and version
+    if (g_opts.help) {
+        options_print_help();
+        return 0;
+    }
+    
+    if (g_opts.version) {
+        options_print_version();
+        return 0;
+    }
+    
+    // Check for errors
+    if (g_opts.error_occurred) {
+        fprintf(stderr, "%s\n", g_opts.error_msg);
+        return 1;
+    }
+    
+    // Check for invalid color before terminal init
+    if (g_opts.color_set && g_opts.color) {
+        if (strcmp(g_opts.color, "green") != 0 &&
            strcmp(g_opts.color, "red") != 0 &&
            strcmp(g_opts.color, "blue") != 0 &&
            strcmp(g_opts.color, "white") != 0 &&
            strcmp(g_opts.color, "yellow") != 0 &&
            strcmp(g_opts.color, "cyan") != 0 &&
            strcmp(g_opts.color, "magenta") != 0 &&
            strcmp(g_opts.color, "black") != 0) {
            fprintf(stderr, " Invalid color selection\n");
            fprintf(stderr, " Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
            return 0;
        }
    }
+
+    // Get terminal size
+    width = 80;
+    height = 24;
+    
+    // Get actual terminal size if possible
+    struct winsize ws;
+    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
+        width = ws.ws_col;
+        height = ws.ws_row;
+    }
+    
+    // Allocate line buffer
+    line_buffer = malloc(width * sizeof(char));
+    if (!line_buffer) {
+        fprintf(stderr, "Error: Memory allocation failed\n");
+        return 1;
+    }
+    
+    // Initialize random seed
+    srand(time(NULL));
+    
+    // Set up signal handler
+    signal(SIGINT, sigint_handler);
+    
+    // Initialize terminal
+    init_terminal();
+    
+    // Set terminal to Linux mode if requested
+    if (g_opts.linux_mode) {
+        setenv("TERM", "linux", 1);
+    }
+    
+    // Print initial screen
+    for (i = 0; i < height; i++) {
+        generate_line(line_buffer, width);
+        print_line(line_buffer, 0);
+        printf("\n");
+    }
+    printf("\n");
+    
+    // Main loop
+    while (1) {
+        // Check for input
+        FD_ZERO(&readfds);
+        FD_SET(STDIN_FILENO, &readfds);
+        
+        tv.tv_sec = g_opts.update_delay;
+        tv.tv_usec = 0;
+        
+        ret = select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv);
+        
+        if (ret > 0 && FD_ISSET(STDIN_FILENO, &readfds)) {
+            char input;
+            if (read(STDIN_FILENO, &input, 1) > 0) {
+                if (input == 'q') {
+                    break;
+                } else if (input == 'a') {
+                    g_opts.async_scroll = !g_opts.async_scroll;
+                } else if (input == 'b') {
+                    g_opts.bold_chars = !g_opts.bold_chars;
+                } else if (input == 'B') {
+                    g_opts.all_bold = 1;
+                    g_opts.bold_chars = 0;
+                } else if (input == 'n') {
+                    g_opts.no_bold = 1;
+                    g_opts.bold_chars = 0;
+                    g_opts.all_bold = 0;
+                } else if (input >= '0' && input <= '9') {
+                    g_opts.update_delay = input - '0';
+                } else if (input == '!') {
+                    // red
+                } else if (input == '@') {
+                    // green
+                } else if (input == '#') {
+                    // yellow
+                } else if (input == '$') {
+                    // blue
+                } else if (input == '%') {
+                    // magenta
+                } else if (input == '^') {
+                    // cyan
+                } else if (input == '&') {
+                    // white
+                } else if (input == ')') {
+                    // black
+                }
+            }
+        }
+        
+        // Update screen
+        for (i = 0; i < height; i++) {
+            generate_line(line_buffer, width);
+            print_line(line_buffer, 0);
+            printf("\n");
+        }
+        printf("\n");
+        
+        // Clear screen and move to top
+        printf("\033[2J\033[H");
+    }
+    
+    // Cleanup
+    free(line_buffer);
+    restore_terminal();
+    
+    return 0;
+}
