#include <sys/ioctl.h>
#include <sys/types.h>
#include "options.h"

// Global options
static Options g_opts;

// Matrix characters
static const char *katakana_chars = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン";
static const char *latin_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

// Terminal state
static struct termios orig_termios;
static int raw_mode = 0;

// Signal handler
static void sigint_handler(int sig) {
    (void)sig;
    if (g_opts.screensaver) {
        exit(0);
    }
}

// Initialize terminal to raw mode
static void init_terminal(void) {
    if (tcgetattr(STDIN_FILENO, &orig_termios) == -1) {
        perror("tcgetattr");
        exit(1);
    }

    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) == -1) {
        perror("tcsetattr");
        exit(1);
    }
    raw_mode = 1;
}

// Restore terminal settings
static void restore_terminal(void) {
    if (raw_mode) {
        if (tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios) == -1) {
            perror("tcsetattr");
            exit(1);
        }
        raw_mode = 0;
    }
}

